import { existsSync, promises as fsp, readFileSync } from "node:fs";
import { homedir as homedir2 } from "node:os";
import { join as join2 } from "node:path";
var DEFAULT_FRESH_MS = 24 * 60 * 60 * 1e3;
function codexLockOwnerMarkerName(ownerId, kind) {
  const safe = ownerId.replace(/[^A-Za-z0-9._-]/g, "_").slice(0, 160) || "unknown";
  return `owner-${safe}-last-${kind}.json`;
}
function parseMarker(raw) {
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}
function readMarker(path) {
  try {
    return parseMarker(readFileSync(path, "utf8"));
  } catch {
    return null;
  }
}
function markerTs(marker) {
  const iso = typeof marker?.ts === "string" ? marker.ts : null;
  const ms = iso ? Date.parse(iso) : Number.NaN;
  return { iso, ms: Number.isFinite(ms) ? ms : 0 };
}
function markerPaths(input) {
  const cacheDir = input.cacheDir ?? process.env.PAPERCUSP_LOCKS_CACHE_DIR ?? join2(homedir2(), ".papercusp/locks-cache");
  return {
    cacheDir,
    decision: join2(cacheDir, codexLockOwnerMarkerName(input.ownerId, "decision")),
    success: join2(cacheDir, codexLockOwnerMarkerName(input.ownerId, "success")),
    error: join2(cacheDir, codexLockOwnerMarkerName(input.ownerId, "error"))
  };
}
function readCodexLockRuntimeVerdict(input) {
  const paths = markerPaths(input);
  return computeCodexLockRuntimeVerdict(input, {
    decision: readMarker(paths.decision),
    success: readMarker(paths.success),
    error: readMarker(paths.error),
    cacheDirExists: existsSync(paths.cacheDir)
  });
}
function computeCodexLockRuntimeVerdict(input, markers) {
  const { decision, success, error } = markers;
  const decisionTs = markerTs(decision);
  const successTs = markerTs(success);
  const errorTs = markerTs(error);
  const nowMs = input.nowMs ?? Date.now();
  const freshMs = input.freshMs ?? DEFAULT_FRESH_MS;
  const decisionOwner = typeof decision?.owner === "string" ? decision.owner : null;
  const decisionMatches = decisionOwner === input.ownerId && decisionTs.ms > 0;
  const successAfterError = successTs.ms > 0 && successTs.ms >= errorTs.ms;
  const fresh = decisionTs.ms > 0 && nowMs - decisionTs.ms <= freshMs;
  const runtimeProbed = decisionMatches && successAfterError;
  let hookHealth;
  if (!input.hooksConfigured) hookHealth = "missing";
  else if (errorTs.ms > successTs.ms) hookHealth = "unhealthy";
  else if (!runtimeProbed) hookHealth = "configured-unverified";
  else if (!fresh) hookHealth = "stale";
  else hookHealth = "verified";
  const lockMode = hookHealth === "verified" ? "automatic" : "manual";
  const reason = hookHealth === "verified" ? "This exact Codex owner has a fresh successful automatic lock decision newer than its last hook error." : hookHealth === "missing" ? "This Codex home has no managed lock-hook configuration." : hookHealth === "unhealthy" ? "This owner\u2019s latest lock-hook error is newer than its latest success." : hookHealth === "stale" ? "This owner\u2019s last successful automatic lock decision is stale." : "Hooks are configured, but this exact Codex owner has not produced a successful runtime decision yet.";
  const effectiveInstruction = lockMode === "automatic" ? "Do not acquire per-edit file locks manually; the verified PreToolUse hook acquires/releases them. Use locks:acquire only for a deliberate multi-file hold." : "Before every file edit, explicitly call locks:acquire and release the returned lock after the atomic edit; do not assume a hook covered it.";
  const generation = Math.max(decisionTs.ms, successTs.ms, errorTs.ms, markers.cacheDirExists ? 1 : 0);
  return {
    lockMode,
    hookHealth,
    runtimeProbed,
    ownerId: input.ownerId,
    hooksConfigured: input.hooksConfigured,
    lastDecisionAt: decisionTs.iso,
    lastSuccessAt: successTs.iso,
    lastErrorAt: errorTs.iso,
    generation,
    reason,
    effectiveInstruction
  };
}

